<?php
/** Tahap 15 — Konfirmasi Pembayaran */
require_once __DIR__ . '/config/auth.php';
require_once __DIR__ . '/includes/order-tracking.php';
$pdo=db();
$error=''; $success=''; $order=null; $paymentCsrf=app_csrf_token(); $code=trim((string)($_POST['code'] ?? $_GET['code'] ?? '')); $phone=trim((string)($_POST['phone'] ?? $_GET['phone'] ?? ''));
$methods=['transfer'=>'Transfer Bank','qris'=>'QRIS','ewallet'=>'E-Wallet','cash'=>'Tunai','other'=>'Lainnya'];
function pay_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function pay_phone($v){$d=preg_replace('/\D+/','',(string)$v)??'';if(str_starts_with($d,'0'))$d='62'.substr($d,1);elseif(str_starts_with($d,'8'))$d='62'.$d;return $d;}
if($pdo){try{$cols=$pdo->query("SHOW COLUMNS FROM orders")->fetchAll(PDO::FETCH_COLUMN);if(!in_array('payment_status',$cols,true))$pdo->exec("ALTER TABLE orders ADD payment_status VARCHAR(20) NOT NULL DEFAULT 'unpaid' AFTER status");if(!in_array('payment_method',$cols,true))$pdo->exec("ALTER TABLE orders ADD payment_method VARCHAR(30) NULL AFTER payment_status");if(!in_array('paid_amount',$cols,true))$pdo->exec("ALTER TABLE orders ADD paid_amount DECIMAL(14,2) NOT NULL DEFAULT 0 AFTER payment_method");if(!in_array('payment_note',$cols,true))$pdo->exec("ALTER TABLE orders ADD payment_note TEXT NULL AFTER paid_amount");if(!in_array('paid_at',$cols,true))$pdo->exec("ALTER TABLE orders ADD paid_at DATETIME NULL AFTER payment_note");}catch(Throwable $e){}}
if(!$pdo){$error='Database belum terhubung.';} elseif($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['submit_payment'])){
  if(!app_verify_csrf($_POST['csrf_token']??'')){ $error='Sesi pembayaran tidak valid. Silakan muat ulang halaman.'; } else {
  $stmt=$pdo->prepare('SELECT * FROM orders WHERE order_code=? LIMIT 1');$stmt->execute([$code]);$order=$stmt->fetch();
  if(!$order){$error='Nomor pesanan tidak ditemukan.';} elseif(pay_phone($phone)!==pay_phone($order['customer_phone'])){$error='Nomor WhatsApp tidak sesuai dengan pesanan.'; $order=null;}
  else{
    $method=$_POST['payment_method']??'';$amount=max(0,(float)($_POST['amount']??0));$note=trim((string)($_POST['note']??''));$file=$_FILES['proof']??null;
    if(!isset($methods[$method]))$error='Pilih metode pembayaran.';
    elseif($amount<=0)$error='Masukkan nominal pembayaran.';
    elseif(!$file || ($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)$error='Silakan upload bukti pembayaran.';
    elseif(($file['error']??0)!==UPLOAD_ERR_OK)$error='Upload bukti pembayaran gagal.';
    elseif((int)$file['size']>5*1024*1024)$error='Ukuran bukti pembayaran maksimal 5 MB.';
    else{
      $finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];
      if(!isset($allowed[$mime]))$error='Bukti harus JPG, PNG, WEBP, atau PDF.';
      else{
        $dir=__DIR__.'/uploads/pembayaran';if(!is_dir($dir))@mkdir($dir,0775,true);$stored='pay_'.bin2hex(random_bytes(12)).'.'.$allowed[$mime];$target=$dir.'/'.$stored;
        if(!move_uploaded_file($file['tmp_name'],$target))$error='Bukti pembayaran tidak dapat disimpan.';
        else{try{
          $pdo->exec("CREATE TABLE IF NOT EXISTS order_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, method VARCHAR(30) NOT NULL, amount DECIMAL(14,2) NOT NULL DEFAULT 0, proof_path VARCHAR(500) NULL, proof_name VARCHAR(255) NULL, note TEXT NULL, status VARCHAR(20) NOT NULL DEFAULT 'waiting', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, INDEX idx_order_payments_order(order_id)) ENGINE=InnoDB");
          $stmt=$pdo->prepare('INSERT INTO order_payments(order_id,method,amount,proof_path,proof_name,note,status) VALUES(?,?,?,?,?,?,?)');$stmt->execute([(int)$order['id'],$method,$amount,'uploads/pembayaran/'.$stored,$file['name'],$note?:null,'waiting']);
          $stmt=$pdo->prepare("UPDATE orders SET payment_status='waiting', payment_method=?, paid_amount=?, payment_note=? WHERE id=?");$stmt->execute([$method,$amount,$note?:null,(int)$order['id']]);
          try { order_record_payment($pdo, (int)$order['id'], 'waiting'); } catch (Throwable $e) {}
          $success='Konfirmasi pembayaran berhasil dikirim. Admin akan memeriksa bukti pembayaran Anda.';
        }catch(Throwable $e){@unlink($target);$error='Konfirmasi pembayaran gagal disimpan.';}}
      }
    }
  }
  }
}
if(!$order && $pdo && $code!=='' && $_SERVER['REQUEST_METHOD']!=='POST'){$stmt=$pdo->prepare('SELECT * FROM orders WHERE order_code=? LIMIT 1');$stmt->execute([$code]);$candidate=$stmt->fetch();if($candidate && pay_phone($phone)===pay_phone($candidate['customer_phone']))$order=$candidate;}
$statusLabels=['unpaid'=>'Belum Bayar','waiting'=>'Menunggu Verifikasi','partial'=>'DP / Sebagian','paid'=>'Lunas','rejected'=>'Ditolak'];
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Konfirmasi Pembayaran — Rosa Indah Printing</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><style>
*{box-sizing:border-box}body{margin:0;background:#fff8fb;color:#18243a;font-family:Arial,Helvetica,sans-serif}.wrap{max-width:760px;margin:35px auto;padding:0 18px}.card{background:#fff;border:1px solid #f0dce7;border-radius:22px;box-shadow:0 18px 50px rgba(214,74,138,.08);padding:30px}.top{display:flex;align-items:center;gap:13px;border-bottom:1px solid #f1e3e9;padding-bottom:20px;margin-bottom:22px}.top img{width:58px;height:58px;object-fit:contain}.top h1{font-size:20px;margin:0}.top span{color:#d64a8a}.sub{color:#7d747c;margin:5px 0 0;font-size:13px}.order-box{background:#fff8fb;border:1px solid #f1dfe8;border-radius:14px;padding:15px;margin-bottom:20px}.order-box strong{display:block;font-size:19px}.order-box p{margin:5px 0;color:#776e75;font-size:13px}.status{display:inline-flex;padding:6px 10px;border-radius:999px;background:#fff1f7;color:#d64a8a;font-size:12px;font-weight:800}.field{margin:15px 0}.field label{display:block;font-size:13px;font-weight:800;margin-bottom:7px}.field input,.field select,.field textarea{width:100%;padding:12px;border:1px solid #eadde3;border-radius:11px;font:inherit}.field textarea{min-height:90px;resize:vertical}.btn{width:100%;border:0;background:#d64a8a;color:#fff;padding:13px;border-radius:11px;font-weight:800;font-size:14px;cursor:pointer}.alert{padding:12px 14px;border-radius:11px;margin-bottom:16px;font-size:13px}.error{background:#fff0f0;color:#a33b3b}.success{background:#eaf8ef;color:#287a47}.linkrow{display:flex;justify-content:space-between;gap:10px;margin-top:15px}.linkrow a{color:#d64a8a;text-decoration:none;font-weight:700;font-size:13px}@media(max-width:600px){.wrap{margin:12px auto;padding:0 10px}.card{padding:20px;border-radius:16px}.linkrow{flex-direction:column}}
</style></head><body><main class="wrap"><section class="card"><div class="top"><img src="<?php echo pay_e(asset_url('images/logo/logori.png')); ?>" alt="Rosa Indah Printing"><div><h1>ROSA INDAH <span>PRINTING</span></h1><p class="sub">Konfirmasi pembayaran pesanan</p></div></div>
<?php if($error): ?><div class="alert error"><?php echo pay_e($error); ?></div><?php endif; ?><?php if($success): ?><div class="alert success"><i class="bi bi-check-circle"></i> <?php echo pay_e($success); ?></div><div class="order-box"><strong><?php echo pay_e($code); ?></strong><p>Status pembayaran: <span class="status">Menunggu Verifikasi</span></p></div><div class="linkrow"><a href="<?php echo page_url('lacak-pesanan.php?code='.urlencode($code).'&phone='.urlencode($phone)); ?>">Lacak Pesanan</a><a href="<?php echo page_url('invoice.php?code='.urlencode($code).'&phone='.urlencode($phone)); ?>">Lihat Nota</a><a href="<?php echo page_url('index.php'); ?>">Kembali ke Website</a></div>
<?php elseif(!$order): ?><h2>Konfirmasi Pembayaran</h2><p class="sub">Masukkan nomor pesanan dan WhatsApp yang digunakan saat checkout.</p><form method="get"><div class="field"><label>Nomor Pesanan</label><input name="code" value="<?php echo pay_e($code); ?>" placeholder="Contoh: RIP-20260820-AB12" required></div><div class="field"><label>Nomor WhatsApp</label><input name="phone" type="tel" value="<?php echo pay_e($phone); ?>" placeholder="08xxxxxxxxxx" required></div><button class="btn" type="submit">Cari Pesanan</button></form>
<?php else: ?><div class="order-box"><strong><?php echo pay_e($order['order_code']); ?></strong><p><?php echo pay_e($order['customer_name']); ?> • Total estimasi Rp<?php echo number_format((float)$order['total_estimate'],0,',','.'); ?></p><span class="status"><?php echo pay_e($statusLabels[$order['payment_status']??'unpaid']??'Belum Bayar'); ?></span></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?php echo pay_e($paymentCsrf); ?>"><input type="hidden" name="code" value="<?php echo pay_e($code); ?>"><input type="hidden" name="phone" value="<?php echo pay_e($phone); ?>"><input type="hidden" name="submit_payment" value="1"><div class="field"><label>Metode Pembayaran</label><select name="payment_method" required><option value="">Pilih metode</option><?php foreach($methods as $k=>$v): ?><option value="<?php echo $k; ?>"><?php echo pay_e($v); ?></option><?php endforeach; ?></select></div><div class="field"><label>Nominal Pembayaran</label><input type="number" name="amount" min="1" step="100" placeholder="Masukkan nominal yang dibayar" required></div><div class="field"><label>Bukti Pembayaran</label><input type="file" name="proof" accept="image/jpeg,image/png,image/webp,application/pdf" required><small style="display:block;color:#8a7f86;margin-top:6px">JPG, PNG, WEBP atau PDF • maksimal 5 MB</small></div><div class="field"><label>Catatan (opsional)</label><textarea name="note" placeholder="Contoh: Transfer BCA a.n. ..."></textarea></div><button class="btn" type="submit"><i class="bi bi-cloud-arrow-up"></i> Kirim Konfirmasi Pembayaran</button></form><div class="linkrow"><a href="<?php echo page_url('invoice.php?code='.urlencode($code).'&phone='.urlencode($phone)); ?>">Lihat Nota</a><a href="<?php echo page_url('index.php'); ?>">Kembali</a></div><?php endif; ?></section></main></body></html>
